import assert from 'node:assert/strict';
import { applyDocument } from '/workspace/src/index.mjs';

test('updates an ordinary writable document in place and increments once', () => {
  const document = { text: 'hello', version: 7 };
  const edits = [{ start: 0, end: 5, text: 'hi' }];
  const result = applyDocument(document, edits);
  assert.strictEqual(result, document);
